<?php declare(strict_types=1); namespace Neok\Pay\Laravel\Http\Middleware; use Closure; use Illuminate\Http\Request; use Neok\Pay\Exceptions\WebhookVerificationException; use Neok\Pay\Webhooks\WebhookVerifier; use Symfony\Component\HttpFoundation\Response;
final class VerifyNeokPayWebhook { public function handle(Request $request,Closure $next): Response {$secret=(string)config('neokpay.webhook_secret');try{$event=(new WebhookVerifier((int)config('neokpay.webhook.timestamp_tolerance',300)))->verify($request->getContent(),(string)$request->header('X-NeokPay-Signature',''),$secret);}catch(WebhookVerificationException){return response()->json(['error'=>'Invalid NEOK Pay webhook.'],400);} $request->attributes->set('neokpay.webhook_event',$event);return $next($request);} }
